Object.entries(all)
        .filter(([id]) => id !== 'fitness' && !excludeIds.has(id))
        .map(([id, pool]) => {
          const excluded = getExcludedPools(id);
          const conflictId = excluded?.find((c) => excludeIds.has(c));
          if (conflictId) {
            const conflict = all[conflictId];
            return {
              id,
              name: pool.name,
              description: pool.description,
              disabledReason: `Mutually exclusive with ${conflict?.name || conflictId}`,
            };
          }
          return { id, name: pool.name, description: pool.description, disabledReason: '' };
        })
        .sort

pools.map((poolSelection) => {
    const pool = getPowerPool(poolSelection.id);
    if (!pool) return null;
    const selectedSet = new Set(poolSelection.powers.map((p) => p.name));
    const selectedInternalNames = poolSelection.powers.map((p) => p.internalName);
    return (
      <AvailablePoolSection
        key={poolSelection.id}
        poolId={poolSelection.id}
        poolName={pool.name}
        allPowers={pool.powers}
        selectedPowerNames={selectedSet}
        level={build.level}
        isPowerLocked={isPowerLocked}
        onSelectPower={(power) => handleSelectPoolPower(poolSelection.id, power)}
        onRemovePower={(power) => removePower('pool', power.internalName)}
        onRemovePool={() => removePool(poolSelection.id)}
        onPowerHover={(power) => handlePowerHover(power, poolSelection.id)}
        onPowerLeave={handlePowerLeave}
        onLockToggle={(power) => handleLockToggle(power, poolSelection.id)}
        onShowInfo={(power, e) => handleShowInfo(power, poolSelection.id, e)}
        color="blue"
        checkAvailability={(power) =>
          isPowerAvailableInPool(poolSelection.id, power, build.level, selectedInternalNames)
        }
        powerLimitReached={pickGateClosed}
        compact={compact}
      />
    );
  }).filter

(() => {
    const selectedPowerInternalNames = new Set<string>();
    const selectedPowersetSlugs = new Set<string>();

    // Collect internal names from selected powers. Include pool + epic
    // picks so intra-pool prerequisites (e.g. Tough requiring Kick or
    // Boxing from the Fighting pool) can resolve.
    for (const p of build.primary.powers) {
      if (p.internalName) selectedPowerInternalNames.add(p.internalName);
    }
    for (const p of build.secondary.powers) {
      if (p.internalName) selectedPowerInternalNames.add(p.internalName);
    }
    for (const pool of build.pools) {
      for (const p of pool.powers) {
        if (p.internalName) selectedPowerInternalNames.add(p.internalName);
      }
    }
    if (build.epicPool) {
      for (const p of build.epicPool.powers) {
        if (p.internalName) selectedPowerInternalNames.add(p.internalName);
      }
    }

    // Collect powerset slugs (e.g., "shield-defense" from "tanker/shield-defense")
    if (build.primary.id) {
      const slug = build.primary.id.split('/')[1];
      if (slug) selectedPowersetSlugs.add(slug);
    }
    if (build.secondary.id) {
      const slug = build.secondary.id.split('/')[1];
      if (slug) selectedPowersetSlugs.add(slug);
    }
    for (const pool of build.pools) {
      if (pool.id) {
        const slug = pool.id.split('/')[1];
        if (slug) selectedPowersetSlugs.add(slug);
      }
    }
    if (build.epicPool?.id) {
      const slug = build.epicPool.id.split('/')[1];
      if (slug) selectedPowersetSlugs.add(slug);
    }

    return {
      selectedPowerDisplayNames: allSelectedPowerNames,
      selectedPowerInternalNames,
      selectedPowersetSlugs,
    };
  })

